export type GetListingsParams = {
  /**
   * Free-text search over title/description/normalized model
   */
  q?: string;
  category?: ListingCategory;
  /**
   * Matched against normalized model (RTX 4090, rtx4090, 4090 all match)
   */
  gpuModel?: string;
  manufacturer?: string;
  minVramGb?: number;
  maxVramGb?: number;
  minPrice?: number;
  maxPrice?: number;
  currency?: string;
  condition?: ListingCondition;
  country?: string;
  region?: string;
  city?: string;
  sourceType?: ListingSourceType;
  /**
   * Defaults to PUBLISHED. A non-public value (DRAFT, PENDING_REVIEW, REJECTED, EXPIRED) requires auth and only ever returns the caller's own listings.
   */
  status?: ListingStatus;
  /**
   * Auth required. Returns only the caller's own listings, in every status — the "My Listings" query.
   */
  mine?: boolean;
  /**
   * When true, returns only listings with at least one photo. Used by the home page grids; leave off on browse/search and My Listings so photo-less listings stay findable.
   */
  hasImages?: boolean;
  sortBy?: ListingSortBy;
  /**
   * @minimum 1
   */
  page?: number;
  /**
   * @minimum 1
   * @maximum 100
   */
  limit?: number;
};

